<?php
namespace App\Controllers\Clinica;use App\Core\Controller;use App\Core\Request;use App\Core\Session;use App\Models\Laboratory;use App\Models\Patient;use App\Models\Catalog;use App\Services\LaboratoryService;use Throwable;
class LaboratorioController extends Controller{public function index(Request $r):void{$q=trim((string)$r->input('q',''));$this->view('laboratorio/index',['title'=>'Laboratorio clínico','exams'=>(new Laboratory())->list(active_environment_id(),$q),'patients'=>(new Patient())->allByEnvironment(active_environment_id()),'types'=>(new Catalog())->labExamTypes(),'search'=>$q,'success'=>Session::pullFlash('success'),'error'=>Session::pullFlash('error')]);}public function store(Request $r):void{if(!Session::validateCsrf($r->input('_token'))){http_response_code(419);return;}try{(new LaboratoryService())->create($r->all(),$r->files(),active_environment_id(),auth_id());Session::flash('success','Examen de laboratorio registrado.');}catch(Throwable $e){Session::flash('error',$e->getMessage());}$this->redirect('/laboratorio');}}
